        return [clamp_step(tgt[0] - src[0]), clamp_step(tgt[1] - src[1])]

    def step_away(src, tgt):
        return [clamp_step(src[0] - tgt[0]), clamp_step(src[1] - tgt[1])]

    env = observation.get("environment_name", "")
    sx, sy = as_xy(observation.get("self_position", (0, 0)))
